import 'dart:io';import 'dart:math';import 'package:path_provider/path_provider.dart';import 'package:http/http.dart' as http;import 'dart:convert';import 'package:flutter/foundation.dart';enum DownloadStatus { pending, downloading, paused, completed, failed }class DownloadTask {  final String regionName;  final double minLat;  final double maxLat;  final double minLon;  final double maxLon;  final int minZoom;  final int maxZoom;  int totalTiles;  int downloadedTiles;  DownloadStatus status;  DateTime createdAt;  DownloadTask({    required this.regionName,    required this.minLat,    required this.maxLat,    required this.minLon,    required this.maxLon,    required this.minZoom,    required this.maxZoom,    this.totalTiles = 0,    this.downloadedTiles = 0,    this.status = DownloadStatus.pending,    DateTime? createdAt,  }) : createdAt = createdAt ?? DateTime.now();  double get progress => totalTiles > 0 ? downloadedTiles / totalTiles : 0;  Map<String, dynamic> toJson() => {        'regionName': regionName,        'minLat': minLat,        'maxLat': maxLat,        'minLon': minLon,        'maxLon': maxLon,        'minZoom': minZoom,        'maxZoom': maxZoom,        'totalTiles': totalTiles,        'downloadedTiles': downloadedTiles,        'status': status.index,        'createdAt': createdAt.toIso8601String(),      };  factory DownloadTask.fromJson(Map<String, dynamic> json) => DownloadTask(        regionName: json['regionName'],        minLat: json['minLat'],        maxLat: json['maxLat'],        minLon: json['minLon'],        maxLon: json['maxLon'],        minZoom: json['minZoom'],        maxZoom: json['maxZoom'],        totalTiles: json['totalTiles'] ?? 0,        downloadedTiles: json['downloadedTiles'] ?? 0,        status: DownloadStatus.values[json['status'] ?? 0],        createdAt: json['createdAt'] != null            ? DateTime.parse(json['createdAt'])            : DateTime.now(),      );}class MapDownloadService {  static const String _tilesDirName = 'offline_tiles';  static const String _tasksFileName = 'download_tasks.json';  static const String _tileServerUrl = 'https://tile.openstreetmap.org';  Future<Directory> getTileDirectory() async {    final appDir = await getApplicationDocumentsDirectory();    final tilesDir = Directory('${appDir.path}/$_tilesDirName');    if (!await tilesDir.exists()) {      await tilesDir.create(recursive: true);    }    return tilesDir;  }  Future<Directory> _getRegionDirectory(String regionName) async {    final tilesDir = await getTileDirectory();    final regionDir =        Directory('${tilesDir.path}/${regionName.replaceAll(' ', '_')}');    if (!await regionDir.exists()) {      await regionDir.create(recursive: true);    }    return regionDir;  }  int _lonToTileX(double lon, int zoom) {    return ((lon + 180.0) / 360.0 * (1 << zoom)).floor();  }  int _latToTileY(double lat, int zoom) {    final latRad = lat * pi / 180.0;    final sinLat = sin(latRad);    final e = exp(-latRad);    final adjusted = (sinLat * (1 + e) / (1 - e)).abs();    return ((1.0 - log(adjusted) / pi) / 2.0 * (1 << zoom)).floor();  }  int _calculateTileCount(double minLat, double maxLat, double minLon,      double maxLon, int minZoom, int maxZoom) {    int count = 0;    for (int z = minZoom; z <= maxZoom; z++) {      final minX = _lonToTileX(minLon, z);      final maxX = _lonToTileX(maxLon, z);      final minY = _latToTileY(maxLat, z);      final maxY = _latToTileY(minLat, z);      count += (maxX - minX + 1) * (maxY - minY + 1);    }    return count;  }  Future<DownloadTask> downloadRegion({    required double minLat,    required double maxLat,    required double minLon,    required double maxLon,    required int minZoom,    required int maxZoom,    required String regionName,    Function(double)? onProgress,  }) async {    final task = DownloadTask(      regionName: regionName,      minLat: minLat,      maxLat: maxLat,      minLon: minLon,      maxLon: maxLon,      minZoom: minZoom,      maxZoom: maxZoom,      status: DownloadStatus.downloading,    );    task.totalTiles =        _calculateTileCount(minLat, maxLat, minLon, maxLon, minZoom, maxZoom);    task.downloadedTiles = 0;    await _saveTask(task);    final regionDir = await _getRegionDirectory(regionName);    for (int z = minZoom; z <= maxZoom; z++) {      final minX = _lonToTileX(minLon, z);      final maxX = _lonToTileX(maxLon, z);      final minY = _latToTileY(maxLat, z);      final maxY = _latToTileY(minLat, z);      for (int x = minX; x <= maxX; x++) {        for (int y = minY; y <= maxY; y++) {          await _downloadTile(z, x, y, regionDir);          task.downloadedTiles++;          onProgress?.call(task.progress);          await _saveTask(task);        }      }    }    task.status = DownloadStatus.completed;    await _saveTask(task);    return task;  }  Future<void> _downloadTile(      int zoom, int x, int y, Directory regionDir) async {    final tileDir = Directory('${regionDir.path}/$zoom/$x');    if (!await tileDir.exists()) {      await tileDir.create(recursive: true);    }    final tileFile = File('${tileDir.path}/$y.png');    if (await tileFile.exists()) return;    try {      final url = '$_tileServerUrl/$zoom/$x/$y.png';      final response = await http.get(Uri.parse(url)).timeout(            const Duration(seconds: 10),          );      if (response.statusCode == 200) {        await tileFile.writeAsBytes(response.bodyBytes);      }    } catch (e) {      debugPrint('Failed to download tile $zoom/$x/$y: $e');    }  }  Future<void> _saveTask(DownloadTask task) async {    final tasks = await getAllDownloads();    final index = tasks.indexWhere((t) => t.regionName == task.regionName);    if (index >= 0) {      tasks[index] = task;    } else {      tasks.add(task);    }    final dir = await getTileDirectory();    final tasksFile = File('${dir.path}/$_tasksFileName');    await tasksFile        .writeAsString(jsonEncode(tasks.map((t) => t.toJson()).toList()));  }  Future<List<DownloadTask>> getAllDownloads() async {    try {      final dir = await getTileDirectory();      final tasksFile = File('${dir.path}/$_tasksFileName');      if (!await tasksFile.exists()) return [];      final content = await tasksFile.readAsString();      final List<dynamic> jsonList = jsonDecode(content);      return jsonList.map((json) => DownloadTask.fromJson(json)).toList();    } catch (e) {      return [];    }  }  Future<int> getStorageUsed() async {    final dir = await getTileDirectory();    int totalSize = 0;    await for (final entity in dir.list(recursive: true)) {      if (entity is File) {        totalSize += await entity.length();      }    }    return totalSize;  }  Future<void> deleteRegion(String regionName) async {    final dir = await getTileDirectory();    final regionDir =        Directory('${dir.path}/${regionName.replaceAll(' ', '_')}');    if (await regionDir.exists()) {      await regionDir.delete(recursive: true);    }    final tasks = await getAllDownloads();    tasks.removeWhere((t) => t.regionName == regionName);    final tasksFile = File('${dir.path}/$_tasksFileName');    await tasksFile        .writeAsString(jsonEncode(tasks.map((t) => t.toJson()).toList()));  }  bool hasTile(int zoom, int x, int y, String regionName) {    final dir = Directory('${getTileDirectory()}/$regionName/$zoom/$x/$y.png');    return false;  }}